-- 00004_service_catalog.up.sql
-- Seeds the portal service catalog for the Discovery Environment, DE-VICE, and Data
-- Commons (data store), mirrored from the canonical (QA/prod) rows. Portal service data
-- is Django-era and not otherwise seeded by migrations. Guarded with ON CONFLICT DO
-- NOTHING so it no-ops where the rows already exist (QA/prod) and populates fresh DBs.
-- Service URLs are the canonical cyverse.org ones; api_form.intercom_team_id carries an
-- inert external id (intercom is disabled), and the intercom/form-group link tables are
-- intentionally omitted.

SET search_path = public, pg_catalog;

BEGIN;

-- api_servicemaintainer
INSERT INTO public.api_servicemaintainer ("id", "name", "website_url", "created_at", "updated_at") VALUES ('1', 'CyVerse', 'http://www.cyverse.org', '2016-12-06 13:51:30.653-07', '2016-12-06 13:51:30.653-07') ON CONFLICT ("id") DO NOTHING;

-- api_service (DE=2, DE-VICE=43, Data Commons=3)
INSERT INTO public.api_service ("id", "name", "description", "about", "service_url", "is_public", "icon_url", "created_at", "updated_at", "service_maintainer_id", "approval_key", "subtitle") VALUES ('2', 'Discovery Environment (DE)', 'Use hundreds of bioinformatics apps and manage data in the CyVerse Data Store from a simple web interface', 'By providing a consistent user interface for access to the tools and computing resources needed for specialized scientific analyses, the Discovery Environment facilitates data exploration and scientific discovery.

### KEY FEATURES
* Access tools and data in the DE with an unprecedented degree of scalability due to its integration with CyVerse’s data management system and compute resources. In the future, the DE will employ provenance tracking of both primary and derived files to track and reproduce experiments.
* Run existing bioinformatics software apps on CyVerse clusters or TACC supercomputers quickly, easily, and efficiently. We offer apps for phylogenetics and systematics, data standardization, transcriptomics and genomics, clustering and network analysis, QTL mapping and GWAS, sequence alignments and phylogenetic tree building, NGS, phylogenetic comparative methods, and trait evolution.
* Use hundreds of command-line analytical tools, utility tools, and scripts, without the need to learn the command line.
* Access, manage, and share data files, workflows, analyses results, and data visualizations with collaborators or with the community at large, knowing your data is safe and accessible within the iRODS data management system.
* Use analytical apps individually or in workflows on local or high-performance computing nodes.
* Easily add any command-line tool or any executable into the tool list, and then create or edit a new customized interface for the app or create a sequenced workflow by chaining one app to another in automated workflow.
* Use application programming interfaces (APIs) for tool integration, resource-intensive analyses, or workflow building.
* Use the same login for all CyVerse resources.

Because much of the complexity is hidden from the user, the DE makes it easy for non-technical users to get the job done simply and easily; no need to master command-line analysis tools or learn new software for every type of analysis. All aspects of your bioinformatics workflow—data management, analysis, sharing large datasets, and more—can be handled within the DE.', 'https://de.cyverse.org', 'true', 'de', '2016-12-06 13:51:30.653-07', '2017-05-30 13:47:41.689467-07', '1', 'DISCOVERY_ENVIRONMENT', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_service ("id", "name", "description", "about", "service_url", "is_public", "icon_url", "created_at", "updated_at", "service_maintainer_id", "approval_key", "subtitle") VALUES ('3', 'Data Commons', 'A unified system for managing and sharing your data across CyVerse''s tools and services', 'Based on a technology called iRODS, CyVerse''s easy-to-use data hosting gives you great flexibility and control over your data. Choose from different interfaces—from web services to mountable file systems to high-speed command-line transfers—to connect your data to every CyVerse platform. To learn how to use the Data Store, see Manage Data.

### KEY FEATURES
Hosting your data in CyVerse''s Data Store allows you to:

* Use your preferred access method to upload, download, and access data from your computer to the Data Store.
* Share your data instantly with other users.
* Keep your data secure by setting permissions to keep your data private only to you, share it with specific collaborators, or make it accessible to the general public (so no account is required).
* Take advantage of parallel data transfers for fast uploads and can handle partial transfers—so if a transfer of 1,000 files or one very large file is interrupted, the process can resume in the same place later.

### ACCESS METHODS
There are a number of different ways with which you can upload, import, and download private or public data in the Data Store. Most require a CyVerse account, but you can access public data anonymously using the Mirrors site (below) without an account, if you don''t have one already set up.', 'http://datacommons.cyverse.org', 'true', 'data-store', '2016-12-06 13:51:30.653-07', '2017-05-30 13:47:34.004028-07', '1', 'DATA_COMMONS', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_service ("id", "name", "description", "about", "service_url", "is_public", "icon_url", "created_at", "updated_at", "service_maintainer_id", "approval_key", "subtitle") VALUES ('43', 'DE - VICE', 'Visual Interactive Computing Environment in the Discovery Environment', 'VICE, which stands for Visual Interactive Computing Environment, is a component of the Discovery Environment (DE), CyVerse’s data science workbench. VICE allows users to launch web-based applications (such as Jupyter and RStudio) from the DE. Once an application is launched users can access the VICE app through a linked URL, import data from the CyVerse Data Store into the application, and pull data from anywhere on the web using standard commands (curl, wget, git).', 'https://de.cyverse.org/de/', 'true', 'vice', '2021-03-30 14:07:02.778824-07', '2021-03-30 14:07:02.778824-07', '1', 'VICE', '') ON CONFLICT ("id") DO NOTHING;

