-- api_form
INSERT INTO public.api_form ("id", "name", "created_at", "updated_at", "description", "explanation", "intercom_team_id", "is_public") VALUES ('2', 'Data Store Shared Folder Request', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', 'Request more data storage for a Community Released data folder you own.', 'The default data storage allocation for each CyVerse user is 100GB and is intended for active data being analyzed. Any data you own or share with other users counts towards your allocation, including [Community Released](http://datacommons.cyverse.org/browse/iplant/home/shared) data in folders that you own. Data that others share with you and data published to the [CyVerse Curated](http://datacommons.cyverse.org/browse/iplant/home/shared/commons_repo/curated) folders of the [Data Commons](http://www.cyverse.org/data-commons-user-agreement) are __excluded__ from your allocation.

If you need more data storage for personal or shared use of a folder that already exists (i.e., your home folder or a Community Released data folder you own), complete and submit this form.

If you need an allocation for a new Community Released data folder, please use the [Request for Community Released Data Folder](https://user.cyverse.org/forms/7/overview) form to request an increased allocation when you request the folder.

Information you provide in the form may be included in CyVerse annual reporting of impacts and resource use to our stakeholders.

**Review process:**


* Requests of 100GB -10TB are usually reviewed within two (2) business days (review level 1)
* Requests of >10TB are usually reviewed within two (2) weeks (review level 2)', '1509745', 'false') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_form ("id", "name", "created_at", "updated_at", "description", "explanation", "intercom_team_id", "is_public") VALUES ('7', 'Community Released Data Folder', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', 'Request to release a publicly-accessible data folder for community data.', '[Community Released](http://datacommons.cyverse.org/browse/iplant/home/shared) data folders are intended for collaborative projects that are producing public datasets that are growing or changing frequently, or that do not need long-term preservation. Along with [CyVerse Curated](http://datacommons.cyverse.org/browse/iplant/home/shared/commons_repo/curated), [Community Released](http://datacommons.cyverse.org/browse/iplant/home/shared) data folders are part of the [Data Commons](http://datacommons.cyverse.org/). Unlike CyVerse Curated data, Community Released datasets do not have permanent identifiers and remain under the control of community members. For more information on storing and sharing data in CyVerse, including full definitions of different data types, please see our [Data Policy](http://www.cyverse.org/data-policy) and [Data Commons User Agreement](http://www.cyverse.org/data-commons-user-agreement).

Community Released data folders may contain some private data (visible only to the owner or community members), but the bulk of the data should be public.

Individuals or groups can request Community Released data folders, but at least one CyVerse user must be specified as an owner.

Community Released data folders must include metadata describing the contents. Before submitting your request, see the wiki page on [Preparing Community Released Data Folders](https://wiki.cyverse.org/wiki/display/DC/Preparing+Community+Released+Data+Folders).', '1574511', 'true') ON CONFLICT ("id") DO NOTHING;

