INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('15', 'Estimated Maximum Data Storage Needed (in GB)', 'number', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '3', '2', 'Please enter a value less than 10 exobytes (1,000,000,000)', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('16', 'Justification for Increase', 'text', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '3', '3', 'Why do you need your allocation increased? Explain how the data are generated and their size. Please include details like what analyses you will be doing, and the size of data generated from your analyses (e.g. size of intermediate output files that can be deleted, size of files that need to be retained). Someone reading your description should be able to determine whether or not the amount of storage being requested is in line with your analysis needs.', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('17', 'What data will be made publicly available?', 'text', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '3', '4', '', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('18', 'What are the timelines for project completion and data release?', 'text', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '4', '0', '', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('19', 'Where will any public data be stored?', 'text', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '4', '1', 'CyVerse supports open data and open science and provides various mechanisms for publishing and sharing data. We generally do not grant increased allocations to single-researcher projects that do not plan to make their data public. If you do not plan to make any of the data public, please use this field to explain why.', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('20', 'Long-term data storage location', 'text', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '4', '2', 'After data analysis is complete, where will you store any remaining data? Include examples: Compress and store locally, public storage provider such as Amazon, DropBox, NCBI, ENSEMBL, etc. CyVerse cannot provide long-term storage of data that is not being actively analyzed.', 'true', '') ON CONFLICT ("id") DO NOTHING;
