INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('70', 'If no, who will be the owner of the folder?', 'char', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '14', '2', 'Please provide their full name, their email, and their CyVerse username', 'false', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('71', 'Data Description', 'text', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '14', '3', 'Describe the contents of the folder, how data were generated, and how they can be used. Also include a description of the community and the work the community is doing.', 'true', '') ON CONFLICT ("id") DO NOTHING;
