INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('75', 'What is your long term plan for storing this data?', 'char', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '15', '2', 'Where will you store the data, should there be a need to move them out of the CyVerse Data Store?', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('76', 'What metadata will you include?', 'char', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '15', '3', 'In addition to the required metadata fields, what other metadata are you including to make your data more better understood and more discoverable?', 'true', '') ON CONFLICT ("id") DO NOTHING;
INSERT INTO public.api_formfield ("id", "name", "type", "created_at", "updated_at", "form_section_id", "index", "description", "is_required", "conversion_key") VALUES ('77', 'I have reviewed the guidelines for preparing a Community Released data folder and agree to supply required metadata.', 'boolean', '2017-03-30 12:01:28.796-07', '2017-03-30 13:05:56.201-07', '15', '4', 'Read [guidelines for preparing a Community Released data folder](https://wiki.cyverse.org/wiki/display/DC/Preparing+Community+Released+Data+Folders)', 'true', '') ON CONFLICT ("id") DO NOTHING;
